const cfg = $('Load Config').first().json;
const filterText = (cfg.emailSubject || '').toLowerCase();
const lookback = Number(cfg.responseRateLookbackCount) || 10;

const resp = $input.first().json;
const list = (resp && (resp.broadcasts || resp.campaigns || resp.results || resp.data))
  || (Array.isArray(resp) ? resp : []);

function messageSubject(b) {
  // Subject usually lives on a nested message/action, not the top-level broadcast object —
  // trying a few likely spots.
  return (b.subject || (b.actions && b.actions[0] && b.actions[0].subject) || (b.message && b.message.subject) || '') + '';
}

const matched = list
  .filter(b => filterText && messageSubject(b).toLowerCase().includes(filterText))
  .sort((a, b) => (b.created_at || b.id || 0) - (a.created_at || a.id || 0))
  .slice(0, lookback);

if (matched.length === 0) {
  return [{ json: { noMatches: true, cfg, __debug_raw_response: resp, __debug_list_length: list.length } }];
}

return matched.map(b => ({ json: { broadcastId: b.id, subject: messageSubject(b), cfg } }));

const cfg = $input.first().json.cfg;
const fallback = Number(cfg.responseRateFallback) || 0.10;
return [{ json: {
  responseRate: fallback,
  clickRate: null,
  conversionFactor: Number(cfg.responseRateConversionFactor) || 0.5,
  source: 'fallback',
  broadcastsUsed: [],
  fallbackRate: fallback,
  maxContactCount: Number(cfg.maxContactCount) || 300,
  reason: 'No matching broadcasts found for filter "' + (cfg.responseRateBroadcastFilter || '') + '".'
} }];

const metricItems = $input.all().map(i => i.json);
const broadcastMeta = $('Filter & Sort Broadcasts').all().map(i => i.json);
const cfg = broadcastMeta[0] && broadcastMeta[0].cfg;

let totalDelivered = 0;
let totalClicked = 0;
const broadcastsUsed = [];

for (let i = 0; i < metricItems.length; i++) {
  const m = metricItems[i].metrics || metricItems[i]; // NOTE: adjust to match actual response shape
  const delivered = Number(m.delivered ?? m.sent ?? 0);
  const clicked = Number(m.clicked ?? 0);
  totalDelivered += delivered;
  totalClicked += clicked;
  broadcastsUsed.push({ id: broadcastMeta[i] && broadcastMeta[i].broadcastId, name: broadcastMeta[i] && broadcastMeta[i].name, delivered, clicked });
}

const conversionFactor = Number(cfg.responseRateConversionFactor) || 0.5;
const fallback = Number(cfg.responseRateFallback) || 0.10;

let responseRate = fallback;
let source = 'fallback';
let clickRate = null;

if (totalDelivered > 0) {
  clickRate = totalClicked / totalDelivered; // NOTE: denominator assumption - delivered, not sent. Adjust if you'd rather use sent.
  responseRate = clickRate * conversionFactor;
  source = 'dynamic';
}

return [{ json: {
  responseRate,
  clickRate,
  conversionFactor,
  source,
  broadcastsUsed,
  fallbackRate: fallback,
  maxContactCount: Number(cfg.maxContactCount) || 300
} }];
